function applyRustPresetCatalog(module, presets) {
	const catalogEntry = MODULE_PRESET_CATALOG_V1.find((entry) => entry.module === module);
	if (!catalogEntry) return;
	const presetsById = new Map(presets.map((preset) => [preset.id, preset]));
	const orderedPresets = [];
	for (const rustPreset of catalogEntry.presets) {
		const matchingPreset = presetsById.get(rustPreset.id);
		if (!matchingPreset) continue;
		orderedPresets.push({
			...matchingPreset,
			label: rustPreset.label
		});
		presetsById.delete(rustPreset.id);
	}
	for (const preset of presets) if (presetsById.has(preset.id)) orderedPresets.push(preset);
	if (orderedPresets.length > 0) presets.splice(0, presets.length, ...orderedPresets);
}
