function withBasePath(path) {
	const base = import.meta.env.BASE_URL || "/";
	return `${base.endsWith("/") ? base : `${base}/`}${path.replace(/^\/+/, "")}`;
}
const pdVisualizerWorkletUrl = withBasePath("czSynthWorklet.js");
const synthWasmUrl = withBasePath("cosmo-synth-engine-wasm/cosmo_synth_engine_bg.wasm");
const synthBindingsUrl = withBasePath("cosmo-synth-engine-wasm/cosmo_synth_engine.js");
//#endregion
export { pdVisualizerWorkletUrl, synthBindingsUrl, synthWasmUrl };
