//#region src/features/synth/engine/modulePresetEvents.ts
const APPLY_MODULE_PRESET_EVENT = "cz-apply-module-preset";
function requestApplyModulePreset(request) {
	if (typeof window === "undefined") return;
	window.dispatchEvent(new CustomEvent(APPLY_MODULE_PRESET_EVENT, { detail: request }));
}
function subscribeApplyModulePreset(handler) {
	const listener = (event) => {
		const detail = event.detail;
		if (!detail) return;
		handler(detail);
	};
	window.addEventListener(APPLY_MODULE_PRESET_EVENT, listener);
	return () => window.removeEventListener(APPLY_MODULE_PRESET_EVENT, listener);
}
//#endregion
export { requestApplyModulePreset, subscribeApplyModulePreset };
