//#region src/lib/synth/drawOscilloscope.ts
/**
* Draw an oscilloscope waveform on a canvas.
* Shared between plugin scope renderer and visualizer.
*/
function drawOscilloscope(canvas, samples, config, pitchHz, sampleRate) {
	const ctx = canvas.getContext("2d");
	if (!ctx) return;
	const dpr = Math.max(2, window.devicePixelRatio || 1);
	const drawWidth = Math.max(1, Math.floor(canvas.clientWidth));
	const drawHeight = Math.max(1, Math.floor(canvas.clientHeight));
	const pixelWidth = Math.floor(drawWidth * dpr);
	const pixelHeight = Math.floor(drawHeight * dpr);
	if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
		canvas.width = pixelWidth;
		canvas.height = pixelHeight;
	}
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	const color = config.color ?? "#3dff3d";
	const gridColor = config.gridColor ?? "rgba(0, 120, 0, 0.35)";
	const triggerMode = config.triggerMode ?? "rise";
	const isUint8 = samples instanceof Uint8Array;
	const triggerFloat = isUint8 ? config.triggerLevel : (config.triggerLevel - 128) / 128;
	if (samples.length === 0) {
		ctx.fillStyle = "#051005";
		ctx.fillRect(0, 0, drawWidth, drawHeight);
		drawGrid(ctx, drawWidth, drawHeight, gridColor);
		return;
	}
	const samplesPerCycle = Math.max(8, Math.round(sampleRate / Math.max(1, pitchHz)));
	const requestedViewSamples = typeof config.fixedWindowSamples === "number" ? Math.round(config.fixedWindowSamples) : Math.round(samplesPerCycle * config.cycles);
	const viewSamples = Math.max(8, Math.min(samples.length - 2, requestedViewSamples));
	if (viewSamples <= 1) {
		ctx.fillStyle = "#051005";
		ctx.fillRect(0, 0, drawWidth, drawHeight);
		drawGrid(ctx, drawWidth, drawHeight, gridColor);
		return;
	}
	let start = typeof config.startIndex === "number" ? Math.max(1, Math.min(samples.length - viewSamples - 1, config.startIndex)) : Math.max(1, Math.floor((samples.length - viewSamples) / 2));
	if (triggerMode !== "off") {
		const endLimit = samples.length - viewSamples - 1;
		for (let i = 1; i < endLimit; i++) {
			const prev = samples[i - 1];
			const curr = samples[i];
			if (triggerMode === "rise" && prev < triggerFloat && curr >= triggerFloat || triggerMode === "fall" && prev > triggerFloat && curr <= triggerFloat) {
				start = i;
				break;
			}
		}
	}
	let mean = 0;
	for (let i = 0; i < viewSamples; i++) mean += samples[start + i];
	mean /= viewSamples;
	ctx.clearRect(0, 0, drawWidth, drawHeight);
	drawGrid(ctx, drawWidth, drawHeight, gridColor);
	ctx.shadowColor = color;
	ctx.shadowBlur = 8;
	ctx.strokeStyle = color;
	ctx.lineWidth = 2;
	ctx.beginPath();
	const amplitudeGain = 5;
	for (let i = 0; i < viewSamples; i++) {
		const x = i / (viewSamples - 1) * drawWidth;
		const sampleValue = samples[start + i];
		const scaledAmplitude = (isUint8 ? (sampleValue - mean) / 128 : sampleValue - mean) * config.verticalZoom * amplitudeGain;
		const y = drawHeight / 2 - scaledAmplitude * (drawHeight / 2 - 8);
		if (i === 0) ctx.moveTo(x, y);
		else ctx.lineTo(x, y);
	}
	ctx.stroke();
	ctx.shadowBlur = 0;
}
function drawGrid(ctx, width, height, color) {
	ctx.strokeStyle = color;
	ctx.lineWidth = 1;
	for (let y = .25; y < 1; y += .25) {
		ctx.beginPath();
		ctx.moveTo(0, height * y);
		ctx.lineTo(width, height * y);
		ctx.stroke();
	}
	for (let x = .1; x < 1; x += .1) {
		ctx.beginPath();
		ctx.moveTo(width * x, 0);
		ctx.lineTo(width * x, height);
		ctx.stroke();
	}
	ctx.strokeStyle = color.replace("0.35", "0.6");
	ctx.lineWidth = 1.5;
	ctx.beginPath();
	ctx.moveTo(0, height / 2);
	ctx.lineTo(width, height / 2);
	ctx.stroke();
}
//#endregion
export { drawOscilloscope };
