//#region src/lib/synth/velocityCurve.ts
/**
* Apply an exponential velocity curve to a normalized velocity [0, 1].
*
* curve = 0  → linear (identity)
* curve > 0  → convex  (more sensitive — high output at low input)
* curve < 0  → concave (less sensitive — needs hard hit for high output)
*/
function applyVelocityCurve(velocity, curve) {
	if (Math.abs(curve) < .001) return velocity;
	const exponent = 2 ** (-curve * 2.5);
	return Math.max(0, Math.min(1, velocity)) ** exponent;
}
//#endregion
export { applyVelocityCurve };
