import { DEFAULT_PRESET } from "../../../lib/synth/presetStorage.mjs";
import { useCallback, useEffect, useRef, useState } from "react";
//#region src/features/synth/hooks/useAudioEngine.ts
const ALL_RUNTIME_MOD_SOURCE_KEYS = Object.keys({
	lfo1: true,
	lfo2: true,
	random: true,
	modEnv: true,
	velocity: true,
	modWheel: true,
	aftertouch: true
});
function buildRuntimeModSources(readValue) {
	return ALL_RUNTIME_MOD_SOURCE_KEYS.reduce((acc, key) => {
		acc[key] = readValue(key);
		return acc;
	}, {});
}
const EMPTY_RUNTIME_MOD_SOURCES = buildRuntimeModSources(() => 0);
const EMPTY_RUNTIME_VOICE_STATES = [];
function createInitialSynthParams() {
	return {
		...JSON.parse(JSON.stringify(DEFAULT_PRESET.params)),
		frequency: 220,
		volume: .4
	};
}
function useAudioEngine({ synthWasmUrl, synthBindingsUrl, pdVisualizerWorkletUrl }) {
	const audioCtxRef = useRef(null);
	const gainNodeRef = useRef(null);
	const analyserNodeRef = useRef(null);
	const workletNodeRef = useRef(null);
	const audioInitRef = useRef(false);
	const [audioContextState, setAudioContextState] = useState(null);
	const paramsRef = useRef(createInitialSynthParams());
	useEffect(() => {
		if (audioInitRef.current) return;
		audioInitRef.current = true;
		let disposed = false;
		const normalizeRuntimeModSources = (value) => {
			if (!value || typeof value !== "object") return null;
			const detail = value;
			const read = (key) => {
				const next = detail[key];
				return typeof next === "number" && Number.isFinite(next) ? next : 0;
			};
			return buildRuntimeModSources(read);
		};
		const normalizeRuntimeVoiceStates = (value) => {
			if (!Array.isArray(value)) return null;
			const readNumber = (source, fallback = 0) => typeof source === "number" && Number.isFinite(source) ? source : fallback;
			const readEnv = (source) => {
				const detail = source && typeof source === "object" ? source : {};
				return {
					value: readNumber(detail.value),
					step: readNumber(detail.step),
					releasing: detail.releasing === true,
					stepPos: readNumber(detail.stepPos),
					prevLevel: readNumber(detail.prevLevel)
				};
			};
			return value.map((entry, index) => {
				const detail = entry && typeof entry === "object" ? entry : {};
				const line1 = detail.line1 && typeof detail.line1 === "object" ? detail.line1 : {};
				const line2 = detail.line2 && typeof detail.line2 === "object" ? detail.line2 : {};
				return {
					index: readNumber(detail.index, index),
					active: detail.active === true,
					isReleasing: detail.isReleasing === true,
					sustained: detail.sustained === true,
					note: typeof detail.note === "number" ? detail.note : null,
					envNote: readNumber(detail.envNote, 60),
					velocity: readNumber(detail.velocity, 0),
					line1: {
						dco: readEnv(line1.dco),
						dcw: readEnv(line1.dcw),
						dca: readEnv(line1.dca)
					},
					line2: {
						dco: readEnv(line2.dco),
						dcw: readEnv(line2.dcw),
						dca: readEnv(line2.dca)
					}
				};
			});
		};
		const init = async () => {
			try {
				const ctx = new AudioContext();
				if (disposed) {
					ctx.close();
					return;
				}
				audioCtxRef.current = ctx;
				ctx.addEventListener("statechange", () => {
					if (!disposed) setAudioContextState(ctx.state);
				});
				const [wasmResponse, bindingsResponse] = await Promise.all([fetch(synthWasmUrl), fetch(synthBindingsUrl)]);
				if (!wasmResponse.ok) throw new Error(`Failed to fetch WASM (${wasmResponse.status}): ${synthWasmUrl}`);
				if (!bindingsResponse.ok) throw new Error(`Failed to fetch WASM bindings (${bindingsResponse.status}): ${synthBindingsUrl}`);
				const [wasmBytes, bindingsJs] = await Promise.all([wasmResponse.arrayBuffer(), bindingsResponse.text()]);
				await ctx.audioWorklet.addModule(pdVisualizerWorkletUrl);
				if (disposed || audioCtxRef.current !== ctx || ctx.state === "closed") {
					await ctx.close().catch(() => {});
					return;
				}
				const workletNode = new AudioWorkletNode(ctx, "cosmo-processor");
				if (disposed) {
					workletNode.disconnect();
					ctx.close();
					return;
				}
				workletNode.port.onmessage = (e) => {
					if (e.data?.type === "ready") {
						workletNodeRef.current = workletNode;
						workletNode.port.postMessage({
							type: "setParams",
							params: paramsRef.current
						});
					} else if (e.data?.type === "runtimeModSources") {
						const sources = normalizeRuntimeModSources(e.data.sources);
						if (sources) window.dispatchEvent(new CustomEvent("cz-runtime-mod-sources", { detail: sources }));
					} else if (e.data?.type === "runtimeVoiceStates") {
						const voices = normalizeRuntimeVoiceStates(e.data.voices);
						if (voices) window.dispatchEvent(new CustomEvent("cz-runtime-voice-states", { detail: voices }));
					} else if (e.data?.type === "error") console.error("[CZ Synth WASM] Worklet error:", e.data.message);
				};
				workletNode.port.postMessage({
					type: "init",
					wasmBytes,
					bindingsJs
				}, [wasmBytes]);
				const gainNode = ctx.createGain();
				gainNode.gain.value = 1;
				const analyserNode = new AnalyserNode(ctx, { fftSize: 2048 });
				workletNode.connect(gainNode);
				gainNode.connect(analyserNode);
				analyserNode.connect(ctx.destination);
				gainNodeRef.current = gainNode;
				analyserNodeRef.current = analyserNode;
			} catch (err) {
				await audioCtxRef.current?.close().catch(() => {});
				audioCtxRef.current = null;
				setAudioContextState(null);
				console.error("[PD Visualizer] Audio init failed:", err);
				audioInitRef.current = false;
			}
		};
		init();
		return () => {
			disposed = true;
			audioInitRef.current = false;
			workletNodeRef.current?.disconnect();
			workletNodeRef.current = null;
			gainNodeRef.current?.disconnect();
			gainNodeRef.current = null;
			analyserNodeRef.current?.disconnect();
			analyserNodeRef.current = null;
			audioCtxRef.current?.close();
			audioCtxRef.current = null;
		};
	}, [
		synthWasmUrl,
		synthBindingsUrl,
		pdVisualizerWorkletUrl
	]);
	return {
		audioCtxRef,
		gainNodeRef,
		analyserNodeRef,
		workletNodeRef,
		paramsRef,
		audioContextState,
		resumeAudio: useCallback(() => {
			const ctx = audioCtxRef.current;
			if (!ctx) return;
			if (ctx.state === "running") {
				setAudioContextState("running");
				return;
			}
			if (ctx.state !== "suspended") return;
			ctx.resume().catch(() => {});
		}, [])
	};
}
//#endregion
export { EMPTY_RUNTIME_MOD_SOURCES, EMPTY_RUNTIME_VOICE_STATES, useAudioEngine };
