import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";
//#region src/features/synth/synthUiStore.ts
const SYNTH_UI_STATE_STORAGE_KEY = "cosmo-pd101-ui-state";
const ASIDE_PANEL_TABS = new Set([
	"scope",
	"global",
	"phaseMod",
	"vibrato",
	"chorus",
	"delay",
	"reverb",
	"phaser"
]);
const MAIN_PANEL_MODES = new Set([
	"phase",
	"fx",
	"mod",
	"waterfall"
]);
const PHASE_LINE_PANEL_TABS = new Set([
	"line1-algos",
	"line2-algos",
	"line1-envelopes",
	"line2-envelopes"
]);
const ENV_TABS = new Set([
	"dco",
	"dcw",
	"dca"
]);
const DEFAULT_UI_STATE = {
	activeAsidePanel: "global",
	mainPanelMode: "phase",
	phaseLinePanelTab: "line1-algos",
	activeEnvTab: "dcw",
	keyboardVisible: true,
	libraryModeOpen: false,
	scopeCycles: 2,
	scopeVerticalZoom: 1,
	scopeTriggerLevel: 128
};
const getStringValue = (value) => typeof value === "string" ? value : null;
const normalizeSynthUiState = (value) => {
	if (typeof value !== "object" || value === null) return DEFAULT_UI_STATE;
	const candidate = value;
	const activeAsidePanel = getStringValue(candidate.activeAsidePanel);
	const mainPanelMode = getStringValue(candidate.mainPanelMode);
	const phaseLinePanelTab = getStringValue(candidate.phaseLinePanelTab);
	const activeEnvTab = getStringValue(candidate.activeEnvTab);
	return {
		activeAsidePanel: activeAsidePanel && ASIDE_PANEL_TABS.has(activeAsidePanel) ? activeAsidePanel : DEFAULT_UI_STATE.activeAsidePanel,
		mainPanelMode: mainPanelMode && MAIN_PANEL_MODES.has(mainPanelMode) ? mainPanelMode : DEFAULT_UI_STATE.mainPanelMode,
		phaseLinePanelTab: phaseLinePanelTab && PHASE_LINE_PANEL_TABS.has(phaseLinePanelTab) ? phaseLinePanelTab : DEFAULT_UI_STATE.phaseLinePanelTab,
		activeEnvTab: activeEnvTab && ENV_TABS.has(activeEnvTab) ? activeEnvTab : DEFAULT_UI_STATE.activeEnvTab,
		keyboardVisible: typeof candidate.keyboardVisible === "boolean" ? candidate.keyboardVisible : DEFAULT_UI_STATE.keyboardVisible,
		libraryModeOpen: typeof candidate.libraryModeOpen === "boolean" ? candidate.libraryModeOpen : DEFAULT_UI_STATE.libraryModeOpen,
		scopeCycles: typeof candidate.scopeCycles === "number" && candidate.scopeCycles >= .5 && candidate.scopeCycles <= 8 ? candidate.scopeCycles : DEFAULT_UI_STATE.scopeCycles,
		scopeVerticalZoom: typeof candidate.scopeVerticalZoom === "number" && candidate.scopeVerticalZoom >= .25 && candidate.scopeVerticalZoom <= 4 ? candidate.scopeVerticalZoom : DEFAULT_UI_STATE.scopeVerticalZoom,
		scopeTriggerLevel: typeof candidate.scopeTriggerLevel === "number" && candidate.scopeTriggerLevel >= 0 && candidate.scopeTriggerLevel <= 255 ? candidate.scopeTriggerLevel : DEFAULT_UI_STATE.scopeTriggerLevel
	};
};
const useSynthUiStore = create()(persist((set) => ({
	...DEFAULT_UI_STATE,
	setActiveAsidePanel: (tab) => set({ activeAsidePanel: tab }),
	setMainPanelMode: (mode) => set({ mainPanelMode: mode }),
	setPhaseLinePanelTab: (tab) => set({ phaseLinePanelTab: tab }),
	setActiveEnvTab: (tab) => set({ activeEnvTab: tab }),
	setKeyboardVisible: (visible) => set({ keyboardVisible: visible }),
	setLibraryModeOpen: (open) => set({ libraryModeOpen: open }),
	setScopeCycles: (cycles) => set({ scopeCycles: cycles }),
	setScopeVerticalZoom: (zoom) => set({ scopeVerticalZoom: zoom }),
	setScopeTriggerLevel: (level) => set({ scopeTriggerLevel: level })
}), {
	name: SYNTH_UI_STATE_STORAGE_KEY,
	storage: createJSONStorage(() => localStorage),
	partialize: (state) => ({
		activeAsidePanel: state.activeAsidePanel,
		mainPanelMode: state.mainPanelMode,
		phaseLinePanelTab: state.phaseLinePanelTab,
		activeEnvTab: state.activeEnvTab,
		keyboardVisible: state.keyboardVisible,
		libraryModeOpen: state.libraryModeOpen,
		scopeCycles: state.scopeCycles,
		scopeVerticalZoom: state.scopeVerticalZoom,
		scopeTriggerLevel: state.scopeTriggerLevel
	}),
	merge: (persistedState, currentState) => ({
		...currentState,
		...normalizeSynthUiState(persistedState)
	})
}));
//#endregion
export { SYNTH_UI_STATE_STORAGE_KEY, useSynthUiStore };
